import json
from pathlib import Path
out=Path('scripts/jk-tilemap-20261111')
s='''var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var cols=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Collider2D>()).Where(c=>c.enabled&&!c.isTrigger&&c.gameObject.layer==6&&(!c.attachedRigidbody||c.attachedRigidbody.bodyType==UnityEngine.RigidbodyType2D.Static)).ToArray();var set=new System.Collections.Generic.HashSet<UnityEngine.Collider2D>(cols);UnityEngine.Physics2D.SyncTransforms();var rows=new System.Collections.Generic.List<string>();for(int y=0;y<630;y++){var line=new System.Text.StringBuilder();for(int x=0;x<60;x++){bool hit=false;foreach(var dx in new[]{.15f,.5f,.85f})foreach(var dy in new[]{.15f,.5f,.85f}){var p=new UnityEngine.Vector2((x+dx)*26.4f/60,-3.6f+(y+dy)*115.36f/630);if(UnityEngine.Physics2D.OverlapPointAll(p).Any(c=>set.Contains(c))){hit=true;break;}}line.Append(hit?'1':'0');}rows.Add(line.ToString());}System.IO.File.WriteAllLines("scripts/jk-tilemap-20261111/current-raster.txt",rows);UnityEngine.Debug.Log("Rasterized existing terrain collider count="+cols.Length);'''
(out/'raster.json').write_text(json.dumps(dict(name='exec_editor_script',arguments=dict(script=s,summary='Record existing fifth-level terrain on original screen coordinates'))))
